  i = skip_ws(t, 0);
  if (i < n  and  _lia_char_code_at(t, i) == 91) {
    cb = match_brack(t, i);
    if (cb > i) { return jss_trim(slice2(t, cb + 1, n)) ;}
  }
  return "";

}

pub fn zig_ty(t: []const u8) []const u8 {
    var out: []const u8 = "";
    var eid: []const u8 = "";

  out = "";
  if (starts_lit(t, 0, "simd8_u32") == 1) { return "@Vector(8, u32)" ;}
  if (starts_lit(t, 0, "simd4_u32") == 1) { return "@Vector(4, u32)" ;}
  if (starts_lit(t, 0, "simd8_u64") == 1) { return "@Vector(8, u64)" ;}
  if (starts_lit(t, 0, "simd4_u64") == 1) { return "@Vector(4, u64)" ;}
  if (starts_lit(t, 0, "simd8_i64") == 1) { return "@Vector(8, i64)" ;}
  if (starts_lit(t, 0, "simd8_u5") == 1) { return "@Vector(8, u5)" ;}
  if (starts_lit(t, 0, "simd8_u6") == 1) { return "@Vector(8, u6)" ;}
  if (is_arr_ty(t) == 1) {
    out = _lia_cat(out ,  "[");
    out = _lia_cat(out ,  arr_n_str(t));
    out = _lia_cat(out ,  "]");
    eid = arr_inner_ident(t);
    if (starts_lit(eid, 0, "simd8_u32") == 1) { out = _lia_cat(out ,  "@Vector(8, u32)") ;}
     else if (starts_lit(eid, 0, "simd4_u32") == 1) { out = _lia_cat(out ,  "@Vector(4, u32)") ;}
     else if (starts_lit(eid, 0, "simd8_u64") == 1) { out = _lia_cat(out ,  "@Vector(8, u64)") ;}
     else if (starts_lit(eid, 0, "simd4_u64") == 1) { out = _lia_cat(out ,  "@Vector(4, u64)") ;}
     else if (starts_lit(eid, 0, "simd8_i64") == 1) { out = _lia_cat(out ,  "@Vector(8, i64)") ;}
     else if (starts_lit(eid, 0, "simd8_u5") == 1) { out = _lia_cat(out ,  "@Vector(8, u5)") ;}
     else if (starts_lit(eid, 0, "simd8_u6") == 1) { out = _lia_cat(out ,  "@Vector(8, u6)") ;}
     else { out = _lia_cat(out ,  "i64") ;}
    return out;
  }
  if (_lia_len(t) == 6  and  starts_lit(t, 0, "string") == 1) { return "[]const u8" ;}
  if (_lia_len(t) == 3  and  starts_lit(t, 0, "str") == 1) { return "[]const u8" ;}
  if (_lia_len(t) == 4  and  starts_lit(t, 0, "bool") == 1) { return "bool" ;}
  if (_lia_len(t) == 3  and  starts_lit(t, 0, "u32") == 1) { return "u32" ;}
  if (_lia_len(t) == 3  and  starts_lit(t, 0, "i32") == 1) { return "i32" ;}
  if (_lia_len(t) == 3  and  starts_lit(t, 0, "u64") == 1) { return "u64" ;}
  if (_lia_len(t) == 3  and  starts_lit(t, 0, "i64") == 1) { return "i64" ;}
  return "i64";

}

pub fn read_type(s: []const u8, k0: i64) []const u8 {
    var k: i64 = 0;
    var n: i64 = 0;
    var cl: i64 = 0;
    var e: i64 = 0;
    var t: []const u8 = "";

  k = skip_ws(s, k0);
  n = _lia_len(s);
  if (k >= n) { return "" ;}
  if (_lia_char_code_at(s, k) == 91) {
    cl = match_brack(s, k);
    if (cl < k) { return "" ;}
    e = skip_ws(s, cl + 1);
    t = read_ident(s, e);
    if (_lia_len(t) == 0) { return "" ;}
    return slice2(s, k, e + _lia_len(t));
  }
  return read_ident(s, k);

}

pub fn skip_type(params: []const u8, k0: i64) i64 {
    var k: i64 = 0;
    var pn: i64 = 0;
    var t: []const u8 = "";

  k = skip_ws(params, k0);
  pn = _lia_len(params);
  if (k < pn  and  _lia_char_code_at(params, k) == 58) {
    k = skip_ws(params, k + 1);
    t = jss_trim(read_type(params, k));
    if (_lia_len(t) > 0) { k = k + _lia_len(t) ;}
  }
  return k;

}

pub fn param_zig_type(params: []const u8, after_id: i64) []const u8 {
    var k: i64 = 0;
    var pn: i64 = 0;
    var t: []const u8 = "";

  k = skip_ws(params, after_id);
  pn = _lia_len(params);
  if (k < pn  and  _lia_char_code_at(params, k) == 58) {
    t = jss_trim(read_type(params, k + 1));
    if (_lia_len(t) > 0) { return zig_ty(t) ;}
  }
  return "i64";

}

pub fn fn_ret_type(src: []const u8, after_paren: i64, brace: i64) []const u8 {
    var k: i64 = 0;
    var t: []const u8 = "";

  k = skip_ws(src, after_paren);
  if (k < brace  and  _lia_char_code_at(src, k) == 45  and  k + 1 < brace  and  _lia_char_code_at(src, k + 1) == 62) {
    t = jss_trim(read_type(src, k + 2));
    if (_lia_len(t) > 0) { return zig_ty(t) ;}
  }
  if (k < brace  and  _lia_char_code_at(src, k) == 58) {
    t = jss_trim(read_type(src, k + 1));
    if (_lia_len(t) > 0) { return zig_ty(t) ;}
  }
  return "i64";

}

pub fn rhs_kind(body: []const u8, eq_pos: i64) []const u8 {
    var n: i64 = 0;
    var k: i64 = 0;
    var id: []const u8 = "";
    var k2: i64 = 0;
    var fld: []const u8 = "";

  n = _lia_len(body);
  k = skip_ws(body, eq_pos + 1);
  if (k >= n) { return "i64" ;}
  if (_lia_char_code_at(body, k) == 34) { return "[]const u8" ;}
  if (_lia_char_code_at(body, k) == 91) { return "i64" ;}
  id = read_ident(body, k);
  if (_lia_len(id) == 0) { return "i64" ;}
  if (starts_lit(id, 0, "true") == 1  or  starts_lit(id, 0, "false") == 1) { return "bool" ;}
  k2 = skip_ws(body, k + _lia_len(id));
  if (k2 < n  and  _lia_char_code_at(body, k2) == 46) {
    fld = read_ident(body, k2 + 1);
    if (starts_lit(fld, 0, "length") == 1  or  starts_lit(fld, 0, "len") == 1  or  starts_lit(fld, 0, "charCodeAt") == 1) { return "i64" ;}
    if (starts_lit(id, 0, "l_int") == 1  or  starts_lit(id, 0, "list_int") == 1  or  starts_lit(id, 0, "int_") == 1) { return "i64" ;}
    return "[]const u8";
  }
  if (starts_lit(id, 0, "list_new_int") == 1) { return "*LiaListI64" ;}
  if (starts_lit(id, 0, "list_new_str") == 1) { return "*LiaListStr" ;}
  if (starts_lit(id, 0, "read_") == 1  or  starts_lit(id, 0, "slice2") == 1  or  starts_lit(id, 0, "q") == 1) { return "[]const u8" ;}
  if (starts_lit(id, 0, "arr_n") == 1  or  starts_lit(id, 0, "arr_inner_") == 1  or  starts_lit(id, 0, "arr_vec_") == 1  or  starts_lit(id, 0, "is_arr_ty") == 1  or  starts_lit(id, 0, "zig_ty") == 1) { return "[]const u8" ;}
  if (starts_lit(id, 0, "js_params") == 1  or  starts_lit(id, 0, "rewrite_") == 1  or  starts_lit(id, 0, "lin_") == 1) { return "[]const u8" ;}
  if (starts_lit(id, 0, "andor") == 1  or  starts_lit(id, 0, "kw_space") == 1  or  starts_lit(id, 0, "zig_") == 1) { return "[]const u8" ;}
  if (starts_lit(id, 0, "emit_") == 1  or  starts_lit(id, 0, "param_") == 1  or  starts_lit(id, 0, "fn_ret") == 1) { return "[]const u8" ;}
  if (starts_lit(id, 0, "rgs_") == 1  or  starts_lit(id, 0, "jss_") == 1  or  starts_lit(id, 0, "jsd_") == 1  or  starts_lit(id, 0, "jsf_") == 1) { return "[]const u8" ;}
  if (starts_lit(id, 0, "cks_") == 1) { return "[]const u8" ;}
  return "i64";

}

pub fn arr_decl_line(id: []const u8, ty: []const u8) []const u8 {
    var out: []const u8 = "";

  out = "    var ";
  out = _lia_cat(out ,  id);
  out = _lia_cat(out ,  ": ");
  out = _lia_cat(out ,  ty);
  if (starts_lit(ty, 0, "[]const u8") == 1) {
    out = _lia_cat(out ,  " = ");
    out = _lia_cat(out ,  q());
    out = _lia_cat(out ,  q());
    out = _lia_cat(out ,  ";\n");
    return out;
  }
  if (_lia_len(ty) > 1  and  _lia_char_code_at(ty, 0) == 91  and  starts_lit(arr_vec_elems(ty), 0, "@Vector") == 1) {
    out = _lia_cat(out ,  " = [_]");
    out = _lia_cat(out ,  arr_vec_elems(ty));
    out = _lia_cat(out ,  "{@splat(0)} ** ");
    out = _lia_cat(out ,  arr_n_str(ty));
    out = _lia_cat(out ,  ";\n");
    return out;
  }
  if (_lia_len(ty) > 1  and  _lia_char_code_at(ty, 0) == 91  and  _lia_char_code_at(ty, 1) >= 48  and  _lia_char_code_at(ty, 1) <= 57) {
    out = _lia_cat(out ,  " = [_]i64{0} ** ");
    out = _lia_cat(out ,  arr_n_str(ty));
    out = _lia_cat(out ,  ";\n");
    return out;
  }
  if (starts_lit(ty, 0, "@Vector") == 1) {
    out = _lia_cat(out ,  " = @splat(0);\n");
    return out;
  }
  if (starts_lit(ty, 0, "*LiaList") == 1) { out = _lia_cat(out ,  " = undefined;\n"); return out ;}
  if (starts_lit(ty, 0, "bool") == 1) { out = _lia_cat(out ,  " = false;\n"); return out ;}
  out = _lia_cat(out ,  " = 0;\n");
  return out;

}

pub fn zig_decls(body: []const u8, params: []const u8) []const u8 {
    var out: []const u8 = "";
    var seen: []const u8 = "";
    var i: i64 = 0;
    var n: i64 = 0;
    var id: []const u8 = "";
    var ty: []const u8 = "";
    var t: []const u8 = "";
    var j: i64 = 0;

  out = "";
  seen = "";
  i = 0;
  n = _lia_len(body);
  id = "";
  ty = "";
  t = "";
  while (i < n) {
    if (_lia_char_code_at(body, i) == 47  and  i + 1 < n  and  _lia_char_code_at(body, i + 1) == 47) {
      i = i + 2;
      while (i < n  and  _lia_char_code_at(body, i) != 10) { i = i + 1 ;}
      if (i < n) { i = i + 1 ;}
      continue;
    }
    if (_lia_char_code_at(body, i) == 34) {
      i = i + 1;
      while (i < n  and  _lia_char_code_at(body, i) != 34) { i = i + 1 ;}
      if (i < n) { i = i + 1 ;}
      continue;
    }
    id = read_ident(body, i);
    if (_lia_len(id) > 0) {
      if (_lia_len(id) == 1  and  _lia_char_code_at(id, 0) == 95) { i = i + 1; continue ;}
      j = skip_ws(body, i + _lia_len(id));
      if (j < n  and  starts_lit(body, j, "=>") == 1) { i = i + _lia_len(id); continue ;}
      if (j < n  and  _lia_char_code_at(body, j) == 58) {
        t = jss_trim(read_type(body, j + 1));
        if (_lia_len(t) > 0  and  in_csv(params, id) == 0  and  in_csv(seen, id) == 0) {
          ty = zig_ty(t);
          out = _lia_cat(out ,  arr_decl_line(id, ty));
          if (_lia_len(seen) == 0) { seen = id ;}
           else { seen = _lia_cat(seen ,  ","); seen = _lia_cat(seen ,  id) ;}
        }
        if (_lia_len(t) > 0) {
          i = skip_ws(body, j + 1);
          i = i + _lia_len(t);
          continue;
        }
      }
      if (j < n  and  _lia_char_code_at(body, j) == 61  and  (j + 1 >= n  or  _lia_char_code_at(body, j + 1) != 61)) {
        if (in_csv(params, id) == 0  and  in_csv(seen, id) == 0) {
          ty = rhs_kind(body, j);
          out = _lia_cat(out ,  arr_decl_line(id, ty));
          if (_lia_len(seen) == 0) { seen = id ;}
           else { seen = _lia_cat(seen ,  ","); seen = _lia_cat(seen ,  id) ;}
        }
      }
      i = i + _lia_len(id);
    }
     else { i = i + 1 ;}
  }
  return out;

}

pub fn arr_prev_ok_index(s: []const u8, i: i64) i64 {
    var k: i64 = 0;

  k = i - 1;
  while (k >= 0  and  (_lia_char_code_at(s, k) == 32  or  _lia_char_code_at(s, k) == 9)) { k = k - 1 ;}
  if (k < 0) { return 0 ;}
  if (is_ident(_lia_char_code_at(s, k)) == true) { return 1 ;}
  if (_lia_char_code_at(s, k) == 41) { return 1 ;}
  if (_lia_char_code_at(s, k) == 93) { return 1 ;}
  return 0;

}

pub fn rewrite_arr(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var chs: []const u8 = "";
    var i: i64 = 0;
    var n: i64 = 0;
    var t: []const u8 = "";
    var cl: i64 = 0;
    var k: i64 = 0;
    var id: []const u8 = "";
    var j: i64 = 0;

  out = "";
  chs = "";
  i = 0;
  n = _lia_len(s);
  t = "";
  cl = 0;
  k = 0;
  while (i < n) {
    if (_lia_char_code_at(s, i) == 47  and  i + 1 < n  and  _lia_char_code_at(s, i + 1) == 47) {
      while (i < n  and  _lia_char_code_at(s, i) != 10) {
        chs = _lia_char_at(s, i);
        out = _lia_cat(out ,  chs);
        i = i + 1;
      }
      if (i < n) { chs = _lia_char_at(s, i); out = _lia_cat(out ,  chs); i = i + 1 ;}
      continue;
    }
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  q());
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) {
        chs = _lia_char_at(s, i);
        out = _lia_cat(out ,  chs);
        i = i + 1;
      }
      if (i < n) { out = _lia_cat(out ,  q()); i = i + 1 ;}
      continue;
    }
    id = read_ident(s, i);
    if (_lia_len(id) > 0) {
      j = skip_ws(s, i + _lia_len(id));
      if (j < n  and  _lia_char_code_at(s, j) == 58) {
        t = jss_trim(read_type(s, j + 1));
        if (_lia_len(t) > 0) {
          k = skip_ws(s, j + 1);
          k = k + _lia_len(t);
          k = skip_ws(s, k);
          if (k < n  and  _lia_char_code_at(s, k) == 61) {
            out = _lia_cat(out ,  id);
            i = k;
            continue;
          }
          while (k < n  and  _lia_char_code_at(s, k) != 59  and  _lia_char_code_at(s, k) != 10) { k = k + 1 ;}
          if (k < n  and  _lia_char_code_at(s, k) == 59) { k = k + 1 ;}
          i = k;
          continue;
        }
      }
      out = _lia_cat(out ,  id);
      i = i + _lia_len(id);
      continue;
    }
    if (_lia_char_code_at(s, i) == 91  and  arr_prev_ok_index(s, i) == 1) {
      cl = match_brack(s, i);
      if (cl > i) {
        out = _lia_cat(out ,  "[_lia_idx(");
        out = _lia_cat(out ,  slice2(s, i + 1, cl));
        out = _lia_cat(out ,  ")]");
        i = cl + 1;
        continue;
      }
    }
    if (_lia_char_code_at(s, i) == 91  and  arr_prev_ok_index(s, i) == 0) {
      cl = match_brack(s, i);
      if (cl > i) {
        out = _lia_cat(out ,  "[_]i64{");
        out = _lia_cat(out ,  slice2(s, i + 1, cl));
        out = _lia_cat(out ,  "}");
        i = cl + 1;
        continue;
      }
    }
    chs = _lia_char_at(s, i);
    out = _lia_cat(out ,  chs);
    i = i + 1;
  }
  return out;

}

pub fn jsf_int_elems(s: []const u8, a: i64, b: i64) i64 {
    var i: i64 = 0;
    var c: i64 = 0;

  i = a;
  c = 0;
  while (i < b) {
    c = _lia_char_code_at(s, i);
    if (c == 32  or  c == 9  or  c == 10  or  c == 13  or  c == 44  or  c == 45) { i = i + 1; continue ;}
    if (c >= 48  and  c <= 57) { i = i + 1; continue ;}
    return 0;
  }
  return 1;

}

pub fn jsf_brackets_ok(body: []const u8) []const u8 {
    var n: i64 = 0;
    var i: i64 = 0;
    var cl: i64 = 0;
    var k: i64 = 0;
    var c: i64 = 0;

  n = _lia_len(body);
  i = 0;
  cl = 0;
  k = 0;
  c = 0;
  while (i < n) {
    c = _lia_char_code_at(body, i);
    if (c == 34  or  c == 39) {
      i = i + 1;
      while (i < n  and  _lia_char_code_at(body, i) != c) { i = i + 1 ;}
      if (i < n) { i = i + 1 ;}
      continue;
    }
    if (c == 91) {
      cl = match_brack(body, i);
      if (cl < i) { return "REJ_INDEX_BRACKET" ;}
      if (arr_prev_ok_index(body, i) == 1) { i = cl + 1; continue ;}
      if (jsf_int_elems(body, i + 1, cl) == 1) { i = cl + 1; continue ;}
      return "REJ_INDEX_BRACKET";
    }
    i = i + 1;
  }
  return "OK";

}

pub fn jss_rev_byte(v: i64) i64 {
    var x: i64 = 0;
    var r: i64 = 0;
    var k: i64 = 0;

  x = v & 255;
  r = 0;
  k = 0;
  while (k < 8) {
    r = _lia_shl(r, 1) | (x & 1);
    x = _lia_shr(x, 1);
    k = k + 1;
  }
  return r & 255;

}

pub fn jss_rev256_assign() []const u8 {
    var out: []const u8 = "";
    var i: i64 = 0;

  out = "  REVERSE_TABLE: [256]int = [";
  i = 0;
  while (i < 256) {
    if (i > 0) { out = _lia_cat(out ,  ", ") ;}
    out = _lia_cat(out ,  rgs_num(jss_rev_byte(i)));
    i = i + 1;
  }
  out = _lia_cat(out ,  "];");
  out = _lia_cat(out ,  rgs_ch(10));
  return out;

}

pub fn match_paren(s: []const u8, open: i64) i64 {
    var n: i64 = 0;
    var depth: i64 = 0;
    var p: i64 = 0;
    var c: i64 = 0;

  n = _lia_len(s);
  depth = 0;
  p = open;
  while (p < n) {
    c = _lia_char_code_at(s, p);
    if (c == 34) {
      p = p + 1;
      while (p < n  and  _lia_char_code_at(s, p) != 34) { p = p + 1 ;}
      if (p < n) { p = p + 1 ;}
      continue;
    }
    if (c == 40) { depth = depth + 1 ;}
     else if (c == 41) {
      depth = depth - 1;
      if (depth == 0) { return p ;}
    }
    p = p + 1;
  }
  return (-1);

}

pub fn starts_lit(s: []const u8, i: i64, lit: []const u8) i64 {
    var n: i64 = 0;
    var ln: i64 = 0;
    var k: i64 = 0;

  n = _lia_len(s);
  ln = _lia_len(lit);
  k = 0;
  while (k < ln) {
    if (i + k >= n) { return 0 ;}
    if (_lia_char_code_at(s, i + k) != _lia_char_code_at(lit, k)) { return 0 ;}
    k = k + 1;
  }
  return 1;

}

pub fn kw_space(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var chs: []const u8 = "";
    var i: i64 = 0;
    var n: i64 = 0;
    var t: i64 = 0;
    var prev: i64 = 0;

  out = "";
  chs = "";
  i = 0;
  n = _lia_len(s);
  t = 0;
  prev = 0;
  while (i < n) {
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  q());
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) {
        chs = _lia_char_at(s, i);
        out = _lia_cat(out ,  chs);
        i = i + 1;
      }
      if (i < n) { out = _lia_cat(out ,  q()); i = i + 1 ;}
      continue;
    }
    if (starts_lit(s, i, "while(") == 1) { out = _lia_cat(out ,  "while ("); i = i + 6; continue ;}
    if (starts_lit(s, i, "if(") == 1) { out = _lia_cat(out ,  "if ("); i = i + 3; continue ;}
    if (i + 1 < n  and  _lia_char_code_at(s, i) == 41  and  _lia_char_code_at(s, i + 1) == 123) { out = _lia_cat(out ,  ") {"); i = i + 2; continue ;}
    if (i + 1 < n  and  _lia_char_code_at(s, i) == 125  and  _lia_char_code_at(s, i + 1) == 59) { out = _lia_cat(out ,  "}"); i = i + 2; continue ;}
    if (_lia_char_code_at(s, i) == 59) {
      t = _lia_len(out);
      while (t > 0) {
        prev = _lia_char_code_at(out, t - 1);
        if (prev == 32  or  prev == 9  or  prev == 10  or  prev == 13) { t = t - 1 ;}
         else { break ;}
      }
      if (t > 0) {
        prev = _lia_char_code_at(out, t - 1);
        if (prev == 59  or  prev == 125) { i = i + 1; continue ;}
      }
      out = _lia_cat(out ,  ";");
      i = i + 1;
      continue;
    }
    chs = _lia_char_at(s, i);
    out = _lia_cat(out ,  chs);
    i = i + 1;
  }
  return out;

}

pub fn rewrite_js_methods(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var chs: []const u8 = "";
    var i: i64 = 0;
    var n: i64 = 0;
    var k: i64 = 0;
    var open: i64 = 0;
    var cl: i64 = 0;
    var id: []const u8 = "";

  out = "";
  chs = "";
  i = 0;
  n = _lia_len(s);
  k = 0;
  open = 0;
  cl = 0;
  id = "";
  while (i < n) {
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  q());
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) {
        chs = _lia_char_at(s, i);
        out = _lia_cat(out ,  chs);
        i = i + 1;
      }
      if (i < n) { out = _lia_cat(out ,  q()); i = i + 1 ;}
      continue;
    }
    if (starts_lit(s, i, "String.fromCharCode(") == 1) {
      open = i + 19;
      cl = match_paren(s, open);
      if (cl > open) {
        out = _lia_cat(out ,  "_lia_from_code(");
        out = _lia_cat(out ,  slice2(s, open + 1, cl));
        out = _lia_cat(out ,  ")");
        i = cl + 1;
        continue;
      }
    }
    if (starts_lit(s, i, "list_new_int()") == 1) {
      out = _lia_cat(out ,  "_lia_list_new_int()");
      i = i + 14;
      continue;
    }
    if (starts_lit(s, i, "list_new_str()") == 1) {
      out = _lia_cat(out ,  "_lia_list_new_str()");
      i = i + 14;
      continue;
    }
    id = read_ident(s, i);
    if (_lia_len(id) > 0) {
      k = i + _lia_len(id);
      if (k < n  and  _lia_char_code_at(s, k) == 46) {
        if (starts_lit(s, k + 1, "charCodeAt(") == 1) {
          open = k + 11;
          cl = match_paren(s, open);
          if (cl > open) {
            out = _lia_cat(out ,  "_lia_char_code_at(");
            out = _lia_cat(out ,  id);
            out = _lia_cat(out ,  ", ");
            out = _lia_cat(out ,  slice2(s, open + 1, cl));
            out = _lia_cat(out ,  ")");
            i = cl + 1;
            continue;
          }
        }
        if (starts_lit(s, k + 1, "charAt(") == 1) {
          open = k + 7;
          cl = match_paren(s, open);
          if (cl > open) {
            out = _lia_cat(out ,  "_lia_char_at(");
            out = _lia_cat(out ,  id);
            out = _lia_cat(out ,  ", ");
            out = _lia_cat(out ,  slice2(s, open + 1, cl));
            out = _lia_cat(out ,  ")");
            i = cl + 1;
            continue;
          }
        }
        if (starts_lit(s, k + 1, "slice(") == 1) {
          open = k + 6;
          cl = match_paren(s, open);
          if (cl > open) {
            out = _lia_cat(out ,  "_lia_slice(");
            out = _lia_cat(out ,  id);
            out = _lia_cat(out ,  ", ");
            out = _lia_cat(out ,  slice2(s, open + 1, cl));
            out = _lia_cat(out ,  ")");
            i = cl + 1;
            continue;
          }
        }
        if (starts_lit(s, k + 1, "length") == 1) {
          out = _lia_cat(out ,  "_lia_len(");
          out = _lia_cat(out ,  id);
          out = _lia_cat(out ,  ")");
          i = k + 7;
          continue;
        }
        if (starts_lit(s, k + 1, "len") == 1  and  (k + 4 >= n  or  is_ident(_lia_char_code_at(s, k + 4)) == false)) {
          out = _lia_cat(out ,  "_lia_len(");
          out = _lia_cat(out ,  id);
          out = _lia_cat(out ,  ")");
          i = k + 4;
          continue;
        }
        if (starts_lit(s, k + 1, "push(") == 1) {
          open = k + 5;
          cl = match_paren(s, open);
          if (cl > open) {
            out = _lia_cat(out ,  "_lia_list_push(");
            out = _lia_cat(out ,  id);
            out = _lia_cat(out ,  ", ");
            out = _lia_cat(out ,  slice2(s, open + 1, cl));
            out = _lia_cat(out ,  ")");
            i = cl + 1;
            continue;
          }
        }
        if (starts_lit(s, k + 1, "get(") == 1) {
          open = k + 4;
          cl = match_paren(s, open);
          if (cl > open) {
            out = _lia_cat(out ,  "_lia_list_get(");
            out = _lia_cat(out ,  id);
            out = _lia_cat(out ,  ", ");
            out = _lia_cat(out ,  slice2(s, open + 1, cl));
            out = _lia_cat(out ,  ")");
            i = cl + 1;
            continue;
          }
        }
        if (starts_lit(s, k + 1, "set(") == 1) {
          open = k + 4;
          cl = match_paren(s, open);
          if (cl > open) {
            out = _lia_cat(out ,  "_lia_list_set(");
            out = _lia_cat(out ,  id);
            out = _lia_cat(out ,  ", ");
            out = _lia_cat(out ,  slice2(s, open + 1, cl));
            out = _lia_cat(out ,  ")");
            i = cl + 1;
            continue;
          }
        }
        if (starts_lit(s, k + 1, "pop()") == 1) {
          out = _lia_cat(out ,  "_lia_list_pop(");
          out = _lia_cat(out ,  id);
          out = _lia_cat(out ,  ")");
          i = k + 6;
          continue;
        }
      }
      out = _lia_cat(out ,  id);
      i = i + _lia_len(id);
      continue;
    }
    chs = _lia_char_at(s, i);
    out = _lia_cat(out ,  chs);
    i = i + 1;
  }
  return out;

}

pub fn atom_is_str(a: []const u8) i64 {
    var c: i64 = 0;

  if (_lia_len(a) == 0) { return 0 ;}
  c = _lia_char_code_at(a, 0);
  if (c == 32  or  c == 9) { return atom_is_str(slice2(a, 1, _lia_len(a))) ;}
  if (c == 34) { return 1 ;}
  if (starts_lit(a, 0, "_lia_len") == 1  or  starts_lit(a, 0, "_lia_char_code_at") == 1) { return 0 ;}
  if (starts_lit(a, 0, "_lia_") == 1) { return 1 ;}
  if (starts_lit(a, 0, "slice2") == 1) { return 1 ;}
  if (starts_lit(a, 0, "read_ident") == 1) { return 1 ;}
  if (starts_lit(a, 0, "out") == 1  and  (_lia_len(a) == 3  or  _lia_char_code_at(a, 3) < 48  or  _lia_char_code_at(a, 3) > 122)) { return 1 ;}
  if (starts_lit(a, 0, "id") == 1  and  _lia_len(a) == 2) { return 1 ;}
  if (starts_lit(a, 0, "src") == 1  and  _lia_len(a) == 3) { return 1 ;}
  if (starts_lit(a, 0, "body") == 1) { return 1 ;}
  if (starts_lit(a, 0, "params") == 1) { return 1 ;}
  if (starts_lit(a, 0, "names") == 1) { return 1 ;}
  if (starts_lit(a, 0, "chs") == 1) { return 1 ;}
  if (starts_lit(a, 0, "js_p") == 1) { return 1 ;}
  if (starts_lit(a, 0, "zig_params") == 1) { return 1 ;}
  if (starts_lit(a, 0, "regions") == 1) { return 1 ;}
  if (starts_lit(a, 0, "chunk") == 1) { return 1 ;}
  if (starts_lit(a, 0, "head") == 1) { return 1 ;}
  if (starts_lit(a, 0, "rgs_") == 1) { return 1 ;}
  if (starts_lit(a, 0, "q()") == 1) { return 1 ;}
  if (starts_lit(a, 0, "csv_") == 1) { return 1 ;}
  if (starts_lit(a, 0, "read_") == 1) { return 1 ;}
  if (starts_lit(a, 0, "curfn") == 1) { return 1 ;}
  if (starts_lit(a, 0, "v") == 1  and  _lia_len(a) == 1) { return 1 ;}
  if (starts_lit(a, 0, "lines") == 1) { return 1 ;}
  if (starts_lit(a, 0, "nm") == 1  and  _lia_len(a) == 2) { return 1 ;}
  if (starts_lit(a, 0, "reason") == 1) { return 1 ;}
  if (starts_lit(a, 0, "pass") == 1) { return 1 ;}
  if (starts_lit(a, 0, "last") == 1) { return 1 ;}
  if (starts_lit(a, 0, "jss_") == 1) { return 1 ;}
  if (starts_lit(a, 0, "cfs_") == 1) { return 1 ;}
  return 0;

}

pub fn atom_is_num(a: []const u8) i64 {
    var c: i64 = 0;

  if (_lia_len(a) == 0) { return 0 ;}
  c = _lia_char_code_at(a, 0);
  if (c == 32  or  c == 9) { return atom_is_num(slice2(a, 1, _lia_len(a))) ;}
  if (c >= 48  and  c <= 57) { return 1 ;}
  if (c == 45) { return 1 ;}
  if (starts_lit(a, 0, "@as") == 1) { return 1 ;}
  if (starts_lit(a, 0, "_lia_char_code") == 1) { return 1 ;}
  if (starts_lit(a, 0, "_lia_len") == 1) { return 1 ;}
  if (starts_lit(a, 0, "_lia_list_len") == 1) { return 1 ;}
  return 0;

}

pub fn rewrite_plus(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var chs: []const u8 = "";
    var i: i64 = 0;
    var n: i64 = 0;
    var L: i64 = 0;
    var R: i64 = 0;
    var left: []const u8 = "";
    var right: []const u8 = "";
    var cut: i64 = 0;
    var take: i64 = 0;
    var c: i64 = 0;
    var id: []const u8 = "";
    var cl: i64 = 0;

  out = "";
  chs = "";
  i = 0;
  n = _lia_len(s);
  L = 0;
  R = 0;
  left = "";
  right = "";
  cut = 0;
  take = 0;
  while (i < n) {
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  q());
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) {
        chs = _lia_char_at(s, i);
        out = _lia_cat(out ,  chs);
        i = i + 1;
      }
      if (i < n) { out = _lia_cat(out ,  q()); i = i + 1 ;}
      continue;
    }
    if (_lia_char_code_at(s, i) == 43) {
      L = i;
      while (L > 0) {
        c = _lia_char_code_at(s, L - 1);
        if (c == 32  or  c == 9) { L = L - 1 ;}
         else { break ;}
      }
      while (L > 0  and  is_ident(_lia_char_code_at(s, L - 1))) { L = L - 1 ;}
      R = skip_ws(s, i + 1);
      if (R < n  and  _lia_char_code_at(s, R) == 34) {
        R = R + 1;
        while (R < n  and  _lia_char_code_at(s, R) != 34) { R = R + 1 ;}
        if (R < n) { R = R + 1 ;}
      }
       else {
        id = read_ident(s, R);
        if (_lia_len(id) > 0) {
          R = R + _lia_len(id);
          if (R < n  and  _lia_char_code_at(s, R) == 40) {
            cl = match_paren(s, R);
            if (cl > R) { R = cl + 1 ;}
          }
        }
         else { R = R + 1 ;}
      }
      left = slice2(s, L, i);
      right = slice2(s, i + 1, R);
      if (atom_is_str(left) == 1  or  atom_is_str(right) == 1) {
        if (atom_is_num(left) == 0  or  atom_is_num(right) == 0) {
          take = i - L;
          cut = _lia_len(out) - take;
          if (cut < 0) { cut = 0 ;}
          out = slice2(out, 0, cut);
          out = _lia_cat(out ,  "_lia_cat(");
          out = _lia_cat(out ,  left);
          out = _lia_cat(out ,  ", ");
          out = _lia_cat(out ,  right);
          out = _lia_cat(out ,  ")");
          i = R;
          continue;
        }
      }
    }
    chs = _lia_char_at(s, i);
    out = _lia_cat(out ,  chs);
    i = i + 1;
  }
  return out;

}

pub fn rewrite_semi(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var chs: []const u8 = "";
    var i: i64 = 0;
    var n: i64 = 0;
    var t: i64 = 0;
    var prev: i64 = 0;

  out = "";
  chs = "";
  i = 0;
  n = _lia_len(s);
  t = 0;
  prev = 0;
  while (i < n) {
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  q());
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) {
        chs = _lia_char_at(s, i);
        out = _lia_cat(out ,  chs);
        i = i + 1;
      }
      if (i < n) { out = _lia_cat(out ,  q()); i = i + 1 ;}
      continue;
    }
    if (_lia_char_code_at(s, i) == 125) {
      t = _lia_len(out);
      while (t > 0) {
        prev = _lia_char_code_at(out, t - 1);
        if (prev == 32  or  prev == 9  or  prev == 10  or  prev == 13) { t = t - 1 ;}
         else { break ;}
      }
      if (t > 0) {
        prev = _lia_char_code_at(out, t - 1);
        if (prev != 59  and  prev != 123  and  prev != 125) { out = _lia_cat(out ,  ";") ;}
      }
      out = _lia_cat(out ,  "}");
      i = i + 1;
    }
     else {
      chs = _lia_char_at(s, i);
      out = _lia_cat(out ,  chs);
      i = i + 1;
    }
  }
  return out;

}

pub fn zig_pipe(body: []const u8) []const u8 {

  return rewrite_arr(kw_space(andor(rewrite_semi(rewrite_plus(rewrite_js_methods(rewrite_body(rewrite_cfor(rewrite_match(body)))))))));

}

pub fn emit_fns(src: []const u8, lang: i64) []const u8 {
    var out: []const u8 = "";
    var name: []const u8 = "";
    var params: []const u8 = "";
    var body: []const u8 = "";
    var js_p: []const u8 = "";
    var zig_params: []const u8 = "";
    var id: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var p: i64 = 0;
    var close_p: i64 = 0;
    var b: i64 = 0;
    var close_b: i64 = 0;
    var k: i64 = 0;
    var pn: i64 = 0;
    var seen: i64 = 0;

  out = "";
  name = "";
  params = "";
  body = "";
  js_p = "";
  zig_params = "";
  id = "";
  n = _lia_len(src);
  i = 0;
  if (lang == 0) { out = "/* generated by lin-rewrite 2.0.0 */\n" ;}
   else { out = "// generated by LIN Zig bootstrap\n" ;}
  while (i < n) {
    i = skip_ws(src, i);
    if (i >= n) { return out ;}
    if (_lia_char_code_at(src, i) == 33  and  (i + 1 >= n  or  _lia_char_code_at(src, i + 1) != 61)) {
      name = read_ident(src, i + 1);
      if (_lia_len(name) > 0) {
        p = skip_ws(src, i + 1 + _lia_len(name));
        if (p < n  and  _lia_char_code_at(src, p) == 40) {
          close_p = p + 1;
          while (close_p < n  and  _lia_char_code_at(src, close_p) != 41) { close_p = close_p + 1 ;}
          params = slice2(src, p + 1, close_p);
          b = find_brace(src, close_p + 1);
          if (b >= 0) {
            close_b = match_brace(src, b);
            if (close_b > b) {
              body = slice2(src, b + 1, close_b);
              js_p = js_params(params);
              if (lang == 0) {
                out = _lia_cat(out ,  "function ");
                out = _lia_cat(out ,  name);
                out = _lia_cat(out ,  "(");
                out = _lia_cat(out ,  js_p);
                out = _lia_cat(out ,  "){");
                out = _lia_cat(out ,  rewrite_body(body));
                out = _lia_cat(out ,  "}\n");
              }
               else {
                zig_params = "";
                k = 0;
                pn = _lia_len(params);
                seen = 0;
                while (k < pn) {
                  k = skip_ws(params, k);
                  if (k >= pn) { break ;}
                  id = read_ident(params, k);
                  if (_lia_len(id) > 0) {
                    if (seen == 1) { zig_params = _lia_cat(zig_params ,  ", ") ;}
                    zig_params = _lia_cat(zig_params ,  id);
                    zig_params = _lia_cat(zig_params ,  ": ");
                    zig_params = _lia_cat(zig_params ,  param_zig_type(params, k + _lia_len(id)));
                    seen = 1;
                    k = skip_type(params, k + _lia_len(id));
                  }
                   else { k = k + 1 ;}
                  while (k < pn  and  _lia_char_code_at(params, k) != 44) { k = k + 1 ;}
                  if (k < pn  and  _lia_char_code_at(params, k) == 44) { k = k + 1 ;}
                }
                out = _lia_cat(out ,  "pub fn ");
                out = _lia_cat(out ,  name);
                out = _lia_cat(out ,  "(");
                out = _lia_cat(out ,  zig_params);
                out = _lia_cat(out ,  ") ");
                out = _lia_cat(out ,  fn_ret_type(src, close_p + 1, b));
                out = _lia_cat(out ,  " {\n");
                out = _lia_cat(out ,  zig_decls(body, js_p));
                out = _lia_cat(out ,  zig_pipe(body));
                out = _lia_cat(out ,  "\n}\n\n");
              }
              i = close_b + 1;
              continue;
            }
          }
        }
      }
    }
    i = i + 1;
  }
  return out;

}

pub fn lin_to_js(src: []const u8) []const u8 {
 return emit_fns(src, 0) ;
}

pub fn lin_to_zig(src: []const u8) []const u8 {
 return emit_fns(src, 1) ;
}

pub fn rewrite_inc(inc: []const u8) []const u8 {
    var out: []const u8 = "";
    var k: i64 = 0;
    var id: []const u8 = "";
    var p: i64 = 0;

  out = "";
  k = skip_ws(inc, 0);
  id = read_ident(inc, k);
  if (_lia_len(id) == 0) { return inc ;}
  p = skip_ws(inc, k + _lia_len(id));
  if (p + 1 < _lia_len(inc)  and  _lia_char_code_at(inc, p) == 43  and  _lia_char_code_at(inc, p + 1) == 43) {
    out = id;
    out = _lia_cat(out ,  " = ");
    out = _lia_cat(out ,  id);
    out = _lia_cat(out ,  " + 1");
    return out;
  }
  return inc;

}

pub fn rewrite_cfor(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var chs: []const u8 = "";
    var i: i64 = 0;
    var n: i64 = 0;
    var cl: i64 = 0;
    var b: i64 = 0;
    var cb: i64 = 0;
    var inner: []const u8 = "";
    var s1: i64 = 0;
    var s2: i64 = 0;
    var k: i64 = 0;

  out = "";
  chs = "";
  i = 0;
  n = _lia_len(s);
  cl = 0;
  b = 0;
  cb = 0;
  inner = "";
  s1 = 0;
  s2 = 0;
  k = 0;
  while (i < n) {
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  q());
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) {
        chs = _lia_char_at(s, i);
        out = _lia_cat(out ,  chs);
        i = i + 1;
      }
      if (i < n) { out = _lia_cat(out ,  q()); i = i + 1 ;}
      continue;
    }
    if (_lia_char_code_at(s, i) == 35  and  i + 1 < n  and  _lia_char_code_at(s, i + 1) == 40) {
      cl = match_paren(s, i + 1);
      if (cl > i + 1) {
        b = find_brace(s, cl + 1);
        if (b >= 0) {
          cb = match_brace(s, b);
          if (cb > b) {
            inner = slice2(s, i + 2, cl);
            s1 = -1;
            s2 = -1;
            k = 0;
            while (k < _lia_len(inner)) {
              if (_lia_char_code_at(inner, k) == 59) {
                if (s1 < 0) { s1 = k ;}
                 else { s2 = k ;}
              }
              k = k + 1;
            }
            if (s1 >= 0  and  s2 > s1) {
              out = _lia_cat(out ,  slice2(inner, 0, s1));
              out = _lia_cat(out ,  ";");
              out = _lia_cat(out ,  "while");
              out = _lia_cat(out ,  "(");
              out = _lia_cat(out ,  slice2(inner, s1 + 1, s2));
              out = _lia_cat(out ,  ")");
              out = _lia_cat(out ,  "{");
              out = _lia_cat(out ,  slice2(s, b + 1, cb));
              out = _lia_cat(out ,  ";");
              out = _lia_cat(out ,  rewrite_inc(slice2(inner, s2 + 1, _lia_len(inner))));
              out = _lia_cat(out ,  ";");
              out = _lia_cat(out ,  "}");
              i = cb + 1;
              continue;
            }
          }
        }
      }
    }
    chs = _lia_char_at(s, i);
    out = _lia_cat(out ,  chs);
    i = i + 1;
  }
  return out;

}

pub fn rewrite_match(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var chs: []const u8 = "";
    var i: i64 = 0;
    var n: i64 = 0;
    var cl: i64 = 0;
    var b: i64 = 0;
    var cb: i64 = 0;
    var expr: []const u8 = "";
    var inner: []const u8 = "";
    var p: i64 = 0;
    var first: i64 = 0;
    var pat: []const u8 = "";
    var j: i64 = 0;
    var ab: i64 = 0;
    var arm: []const u8 = "";

  out = "";
  chs = "";
  i = 0;
  n = _lia_len(s);
  cl = 0;
  b = 0;
  cb = 0;
  expr = "";
  inner = "";
  p = 0;
  first = 0;
  pat = "";
  j = 0;
  ab = 0;
  arm = "";
  while (i < n) {
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  q());
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) {
        chs = _lia_char_at(s, i);
        out = _lia_cat(out ,  chs);
        i = i + 1;
      }
      if (i < n) { out = _lia_cat(out ,  q()); i = i + 1 ;}
      continue;
    }
    if (starts_lit(s, i, "match(") == 1) {
      cl = match_paren(s, i + 5);
      if (cl > i) {
        b = find_brace(s, cl + 1);
        if (b >= 0) {
          cb = match_brace(s, b);
          if (cb > b) {
            expr = slice2(s, i + 6, cl);
            inner = slice2(s, b + 1, cb);
            p = 0;
            first = 1;
            while (p < _lia_len(inner)) {
              p = skip_ws(inner, p);
              if (p >= _lia_len(inner)) { break ;}
              if (_lia_char_code_at(inner, p) == 95) {
                p = skip_ws(inner, p + 1);
                if (p + 1 < _lia_len(inner)  and  _lia_char_code_at(inner, p) == 61  and  _lia_char_code_at(inner, p + 1) == 62) {
                  p = skip_ws(inner, p + 2);
                  if (p < _lia_len(inner)  and  _lia_char_code_at(inner, p) == 123) {
                    ab = match_brace(inner, p);
                    if (ab > p) {
                      arm = slice2(inner, p + 1, ab);
                      if (first == 1) { out = _lia_cat(out ,  "{") ;}
                       else { out = _lia_cat(out ,  ":{") ;}
                      out = _lia_cat(out ,  arm);
                      out = _lia_cat(out ,  "}");
                      first = 0;
                      p = ab + 1;
                      continue;
                    }
                  }
                }
              }
              pat = "";
              if (_lia_char_code_at(inner, p) >= 48  and  _lia_char_code_at(inner, p) <= 57) {
                j = p;
                while (j < _lia_len(inner)  and  _lia_char_code_at(inner, j) >= 48  and  _lia_char_code_at(inner, j) <= 57) { j = j + 1 ;}
                pat = slice2(inner, p, j);
                p = j;
              }
               else {
                pat = read_ident(inner, p);
                if (_lia_len(pat) == 0) { break ;}
                p = p + _lia_len(pat);
              }
              p = skip_ws(inner, p);
              if (p + 1 < _lia_len(inner)  and  _lia_char_code_at(inner, p) == 61  and  _lia_char_code_at(inner, p + 1) == 62) {
                p = skip_ws(inner, p + 2);
                if (p < _lia_len(inner)  and  _lia_char_code_at(inner, p) == 123) {
                  ab = match_brace(inner, p);
                  if (ab > p) {
                    arm = slice2(inner, p + 1, ab);
                    if (first == 1) { out = _lia_cat(out ,  "?(") ;}
                     else { out = _lia_cat(out ,  ":?(") ;}
                    out = _lia_cat(out ,  expr);
                    out = _lia_cat(out ,  "==");
                    out = _lia_cat(out ,  pat);
                    out = _lia_cat(out ,  "){");
                    out = _lia_cat(out ,  arm);
                    out = _lia_cat(out ,  "}");
                    first = 0;
                    p = ab + 1;
                    continue;
                  }
                }
              }
              break;
            }
            i = cb + 1;
            continue;
          }
        }
      }
    }
    chs = _lia_char_at(s, i);
    out = _lia_cat(out ,  chs);
    i = i + 1;
  }
  return out;

}

pub fn rgs_ch(c: i64) []const u8 {
 return _lia_from_code(c) ;
}

pub fn rg_digit(x: i64, p: i64) i64 {
    var d: i64 = 0;
    var y: i64 = 0;

  d = 0;
  y = x;
  while (y >= p) { y = y - p; d = d + 1 ;}
  return d;

}

pub fn rg_rem(x: i64, p: i64) i64 {
    var y: i64 = 0;

  y = x;
  while (y >= p) { y = y - p ;}
  return y;

}

pub fn rgs_num(v: i64) []const u8 {
    var out: []const u8 = "";
    var x: i64 = 0;
    var started: i64 = 0;
    var d: i64 = 0;
    var p: i64 = 0;

  if (v <= 0) { return "0" ;}
  out = "";
  x = v;
  started = 0;
  d = 0;
  p = 10000;
  while (p >= 1) {
    d = rg_digit(x, p);
    x = rg_rem(x, p);
    if (d > 0  or  started == 1  or  p == 1) {
      out = _lia_cat(out ,  rgs_ch(48 + d));
      started = 1;
    }
    if (p == 10000) { p = 1000 ;}
     else if (p == 1000) { p = 100 ;}
     else if (p == 100) { p = 10 ;}
     else if (p == 10) { p = 1 ;}
     else { p = 0 ;}
  }
  return out;

}

pub fn rg_count_lit(hay: []const u8, needle: []const u8) i64 {
    var n: i64 = 0;
    var i: i64 = 0;
    var cnt: i64 = 0;

  n = _lia_len(hay);
  i = 0;
  cnt = 0;
  while (i < n) {
    if (starts_lit(hay, i, needle) == 1) { cnt = cnt + 1 ;}
    i = i + 1;
  }
  return cnt;

}

pub fn rg_is_kw(id: []const u8) i64 {

  if (in_csv("while,break,continue,if,else,for,true,false,return,match,String,fromCharCode", id) == 1) { return 1 ;}
  return 0;

}

pub fn rgs_csv_add(csv: []const u8, id: []const u8) []const u8 {
    var out: []const u8 = "";

  out = "";
  if (_lia_len(id) == 0) { out = _lia_cat(out ,  csv); return out ;}
  if (in_csv(csv, id) == 1) { out = _lia_cat(out ,  csv); return out ;}
  if (_lia_len(csv) == 0) { out = _lia_cat(out ,  id); return out ;}
  out = _lia_cat(out ,  csv);
  out = _lia_cat(out ,  ",");
  out = _lia_cat(out ,  id);
  return out;

}

pub fn rg_csv_end(csv: []const u8, k: i64) i64 {
    var n: i64 = 0;
    var p: i64 = 0;

  n = _lia_len(csv);
  p = k;
  while (p < n  and  _lia_char_code_at(csv, p) != 44) { p = p + 1 ;}
  return p;

}

pub fn rgs_csv_merge(a: []const u8, b: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var k: i64 = 0;
    var e: i64 = 0;
    var id: []const u8 = "";

  out = "";
  out = _lia_cat(out ,  a);
  n = _lia_len(b);
  k = 0;
  e = 0;
  id = "";
  while (k < n) {
    e = rg_csv_end(b, k);
    id = slice2(b, k, e);
    out = rgs_csv_add(out, id);
    k = e + 1;
  }
  return out;

}

pub fn rgs_csv_minus(csv: []const u8, rm: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var k: i64 = 0;
    var e: i64 = 0;
    var id: []const u8 = "";

  out = "";
  n = _lia_len(csv);
  k = 0;
  e = 0;
  id = "";
  while (k < n) {
    e = rg_csv_end(csv, k);
    id = slice2(csv, k, e);
    if (in_csv(rm, id) == 0) { out = rgs_csv_add(out, id) ;}
    k = e + 1;
  }
  return out;

}

pub fn rgs_csv_inter(a: []const u8, b: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var k: i64 = 0;
    var e: i64 = 0;
    var id: []const u8 = "";

  out = "";
  n = _lia_len(a);
  k = 0;
  e = 0;
  id = "";
  while (k < n) {
    e = rg_csv_end(a, k);
    id = slice2(a, k, e);
    if (in_csv(b, id) == 1) { out = rgs_csv_add(out, id) ;}
    k = e + 1;
  }
  return out;

}

pub fn rg_is_assign(body: []const u8, p: i64) i64 {
    var n: i64 = 0;
    var c: i64 = 0;

  n = _lia_len(body);
  if (p >= n) { return 0 ;}
  c = _lia_char_code_at(body, p);
  if (c == 61) {
    if (p + 1 < n  and  _lia_char_code_at(body, p + 1) == 61) { return 0 ;}
    return 1;
  }
  if (c == 43  or  c == 45  or  c == 42) {
    if (p + 1 < n  and  _lia_char_code_at(body, p + 1) == 61) { return 1 ;}
  }
  return 0;

}

pub fn rg_is_compound(body: []const u8, p: i64) i64 {
    var n: i64 = 0;
    var c: i64 = 0;

  n = _lia_len(body);
  if (p >= n) { return 0 ;}
  c = _lia_char_code_at(body, p);
  if (c == 43  or  c == 45  or  c == 42) {
    if (p + 1 < n  and  _lia_char_code_at(body, p + 1) == 61) { return 1 ;}
  }
  return 0;

}

pub fn rgs_scan(body: []const u8, mode: i64) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var c: i64 = 0;
    var id: []const u8 = "";
    var p: i64 = 0;
    var member: i64 = 0;

  out = "";
  n = _lia_len(body);
  i = 0;
  c = 0;
  id = "";
  p = 0;
  member = 0;
  while (i < n) {
    c = _lia_char_code_at(body, i);
    if (c == 34) {
      i = i + 1;
      while (i < n  and  _lia_char_code_at(body, i) != 34) { i = i + 1 ;}
      i = i + 1;
      continue;
    }
    if (c == 47  and  i + 1 < n  and  _lia_char_code_at(body, i + 1) == 47) {
      while (i < n  and  _lia_char_code_at(body, i) != 10) { i = i + 1 ;}
      continue;
    }
    if (is_ident_start(c) == true) {
      id = read_ident(body, i);
      member = 0;
      if (i > 0  and  _lia_char_code_at(body, i - 1) == 46) { member = 1 ;}
      p = skip_ws(body, i + _lia_len(id));
      if (member == 0  and  rg_is_kw(id) == 0) {
        if (mode == 3  and  p < n  and  _lia_char_code_at(body, p) == 40) { out = rgs_csv_add(out, id) ;}
        if (mode == 2  and  rg_is_assign(body, p) == 1) { out = rgs_csv_add(out, id) ;}
        if (mode == 1  and  rg_is_compound(body, p) == 1) { out = rgs_csv_add(out, id) ;}
        if (mode == 1  and  rg_is_assign(body, p) == 0) {
          if (p >= n  or  _lia_char_code_at(body, p) != 40) { out = rgs_csv_add(out, id) ;}
        }
      }
      i = i + _lia_len(id);
      continue;
    }
    i = i + 1;
  }
  return out;

}

pub fn rgs_induction(body: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var c: i64 = 0;
    var id: []const u8 = "";
    var id2: []const u8 = "";
    var p: i64 = 0;

  out = "";
  n = _lia_len(body);
  i = 0;
  c = 0;
  id = "";
  id2 = "";
  p = 0;
  while (i < n) {
    c = _lia_char_code_at(body, i);
    if (c == 34) {
      i = i + 1;
      while (i < n  and  _lia_char_code_at(body, i) != 34) { i = i + 1 ;}
      i = i + 1;
      continue;
    }
    if (is_ident_start(c) == true) {
      id = read_ident(body, i);
      p = skip_ws(body, i + _lia_len(id));
      if (p + 1 < n  and  _lia_char_code_at(body, p) == 43  and  _lia_char_code_at(body, p + 1) == 43) {
        out = rgs_csv_add(out, id);
      }
      if (p < n  and  _lia_char_code_at(body, p) == 61) {
        if (p + 1 >= n  or  _lia_char_code_at(body, p + 1) != 61) {
          p = skip_ws(body, p + 1);
          id2 = read_ident(body, p);
          if (_lia_len(id2) > 0  and  in_csv(id, id2) == 1) {
            p = skip_ws(body, p + _lia_len(id2));
            if (p < n  and  (_lia_char_code_at(body, p) == 43  or  _lia_char_code_at(body, p) == 45)) {
              p = skip_ws(body, p + 1);
              if (p < n  and  _lia_char_code_at(body, p) >= 48  and  _lia_char_code_at(body, p) <= 57) {
                out = rgs_csv_add(out, id);
              }
            }
          }
        }
      }
      i = i + _lia_len(id);
      continue;
    }
    i = i + 1;
  }
  return out;

}

pub fn rgs_verdict(head: []const u8, body: []const u8) []const u8 {
    var calls: []const u8 = "";
    var ind: []const u8 = "";
    var w: []const u8 = "";
    var r: []const u8 = "";
    var carried: []const u8 = "";

  calls = rgs_scan(body, 3);
  if (_lia_len(calls) > 0) { return "UNKNOWN" ;}
  if (_lia_len(head) == 0) { return "PROVED" ;}
  ind = rgs_csv_merge(rgs_induction(head), rgs_induction(body));
  w = rgs_csv_minus(rgs_scan(body, 2), ind);
  if (_lia_len(w) == 0) { return "PROVED" ;}
  r = rgs_csv_minus(rgs_scan(body, 1), ind);
  carried = rgs_csv_inter(w, r);
  if (_lia_len(carried) > 0) { return "FALSE" ;}
  return "UNKNOWN";

}

pub fn rgs_reason(head: []const u8, body: []const u8) []const u8 {
    var calls: []const u8 = "";
    var ind: []const u8 = "";
    var w: []const u8 = "";
    var r: []const u8 = "";
    var carried: []const u8 = "";

  calls = rgs_scan(body, 3);
  if (_lia_len(calls) > 0) { return "calls_with_unproven_effects" ;}
  if (_lia_len(head) == 0) { return "pure_scalar_map_parallel" ;}
  ind = rgs_csv_merge(rgs_induction(head), rgs_induction(body));
  w = rgs_csv_minus(rgs_scan(body, 2), ind);
  if (_lia_len(w) == 0) { return "read_only_region_no_write_conflict" ;}
  r = rgs_csv_minus(rgs_scan(body, 1), ind);
  carried = rgs_csv_inter(w, r);
  if (_lia_len(carried) > 0) { return "loop_carried_dependency" ;}
  return "writes_to_unproven_locations";

}

pub fn rgs_emit(rid: i64, fname: []const u8, kind: []const u8, head: []const u8, body: []const u8) []const u8 {
    var ind: []const u8 = "";
    var out: []const u8 = "";

  ind = rgs_csv_merge(rgs_induction(head), rgs_induction(body));
  out = "  .R";
  out = _lia_cat(out ,  rgs_num(rid));
  out = _lia_cat(out ,  "{ fn=");
  out = _lia_cat(out ,  fname);
  out = _lia_cat(out ,  " kind=");
  out = _lia_cat(out ,  kind);
  out = _lia_cat(out ,  " induction=");
  out = _lia_cat(out ,  q());
  out = _lia_cat(out ,  ind);
  out = _lia_cat(out ,  q());
  out = _lia_cat(out ,  " reads=");
  out = _lia_cat(out ,  q());
  out = _lia_cat(out ,  rgs_csv_minus(rgs_scan(body, 1), ind));
  out = _lia_cat(out ,  q());
  out = _lia_cat(out ,  " writes=");
  out = _lia_cat(out ,  q());
  out = _lia_cat(out ,  rgs_csv_minus(rgs_scan(body, 2), ind));
  out = _lia_cat(out ,  q());
  out = _lia_cat(out ,  " calls=");
  out = _lia_cat(out ,  q());
  out = _lia_cat(out ,  rgs_scan(body, 3));
  out = _lia_cat(out ,  q());
  out = _lia_cat(out ,  " parallel_safe=");
  out = _lia_cat(out ,  rgs_verdict(head, body));
  out = _lia_cat(out ,  " reason=");
  out = _lia_cat(out ,  rgs_reason(head, body));
  out = _lia_cat(out ,  " }");
  out = _lia_cat(out ,  rgs_ch(10));
  return out;

}

pub fn rgs_body(src: []const u8) []const u8 {
    var out: []const u8 = "";
    var body: []const u8 = "";
    var head: []const u8 = "";
    var curfn: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var c: i64 = 0;
    var rid: i64 = 0;
    var cl: i64 = 0;
    var b: i64 = 0;
    var cb: i64 = 0;
    var p: i64 = 0;
    var fn_body: []const u8 = "";

  out = "";
  body = "";
  head = "";
  curfn = "";
  n = _lia_len(src);
  i = 0;
  c = 0;
  rid = 0;
  cl = 0;
  b = 0;
  cb = 0;
  p = 0;
  while (i < n) {
    c = _lia_char_code_at(src, i);
    if (c == 34) {
      i = i + 1;
      while (i < n  and  _lia_char_code_at(src, i) != 34) { i = i + 1 ;}
      i = i + 1;
      continue;
    }
    if (c == 47  and  i + 1 < n  and  _lia_char_code_at(src, i + 1) == 47) {
      while (i < n  and  _lia_char_code_at(src, i) != 10) { i = i + 1 ;}
      continue;
    }
    if (c == 33  and  (i + 1 >= n  or  _lia_char_code_at(src, i + 1) != 61)) {
      curfn = read_ident(src, i + 1);
      if (_lia_len(curfn) > 0) {
        p = skip_ws(src, i + 1 + _lia_len(curfn));
        if (p < n  and  _lia_char_code_at(src, p) == 40) {
          cl = match_paren(src, p);
          if (cl > p) {
            b = find_brace(src, cl + 1);
            if (b >= 0) {
              cb = match_brace(src, b);
              if (cb > b) {
                fn_body = slice2(src, b + 1, cb);
                if (rg_count_lit(fn_body, "#(") == 0  and  rg_count_lit(fn_body, "while") == 0) {
                  rid = rid + 1;
                  out = _lia_cat(out ,  rgs_emit(rid, curfn, "scalar_map", "", fn_body));
                }
              }
            }
          }
        }
      }
      i = i + 1;
      continue;
    }
    if (c == 35  and  i + 1 < n  and  _lia_char_code_at(src, i + 1) == 40) {
      cl = match_paren(src, i + 1);
      if (cl > i + 1) {
        b = find_brace(src, cl + 1);
        if (b >= 0) {
          cb = match_brace(src, b);
          if (cb > b) {
            head = slice2(src, i + 2, cl);
            body = slice2(src, b + 1, cb);
            rid = rid + 1;
            out = _lia_cat(out ,  rgs_emit(rid, curfn, "for", head, body));
            i = b + 1;
            continue;
          }
        }
      }
    }
    if (starts_lit(src, i, "while") == 1) {
      p = skip_ws(src, i + 5);
      if (p < n  and  _lia_char_code_at(src, p) == 40) {
        cl = match_paren(src, p);
        if (cl > p) {
          b = find_brace(src, cl + 1);
          if (b >= 0) {
            cb = match_brace(src, b);
            if (cb > b) {
              head = slice2(src, p + 1, cl);
              body = slice2(src, b + 1, cb);
              rid = rid + 1;
              out = _lia_cat(out ,  rgs_emit(rid, curfn, "while", head, body));
              i = b + 1;
              continue;
            }
          }
        }
      }
    }
    i = i + 1;
  }
  return out;

}

pub fn rgs_regions(src: []const u8) []const u8 {
    var out: []const u8 = "";
    var body: []const u8 = "";

  out = "";
  body = "";
  body = _lia_cat(body ,  rgs_body(src));
  out = _lia_cat(out ,  "@RULEL:LIN_REGIONS:1.0.0");
  out = _lia_cat(out ,  rgs_ch(10));
  out = _lia_cat(out ,  ".policy{ states=PROVED|FALSE|UNKNOWN default=UNKNOWN fail_closed=true }");
  out = _lia_cat(out ,  rgs_ch(10));
  out = _lia_cat(out ,  ".regions{");
  out = _lia_cat(out ,  rgs_ch(10));
  out = _lia_cat(out ,  body);
  out = _lia_cat(out ,  "}");
  out = _lia_cat(out ,  rgs_ch(10));
  out = _lia_cat(out ,  ".summary{ total=");
  out = _lia_cat(out ,  rgs_num(rg_count_lit(body, "parallel_safe=")));
  out = _lia_cat(out ,  " proved=");
  out = _lia_cat(out ,  rgs_num(rg_count_lit(body, "parallel_safe=PROVED")));
  out = _lia_cat(out ,  " dependent=");
  out = _lia_cat(out ,  rgs_num(rg_count_lit(body, "parallel_safe=FALSE")));
  out = _lia_cat(out ,  " unknown=");
  out = _lia_cat(out ,  rgs_num(rg_count_lit(body, "parallel_safe=UNKNOWN")));
  out = _lia_cat(out ,  " }");
  out = _lia_cat(out ,  rgs_ch(10));
  return out;

}

pub fn jsx_has(set: []const u8, ch: i64) i64 {
    var k: i64 = 0;

  k = 0;
  while (k < _lia_len(set)) {
    if (_lia_char_code_at(set, k) == ch) { return 1 ;}
    k = k + 1;
  }
  return 0;

}

pub fn jsx_prev_value(s: []const u8, i: i64) i64 {
    var k: i64 = 0;
    var c: i64 = 0;

  k = i - 1;
  while (k >= 0  and  (_lia_char_code_at(s, k) == 32  or  _lia_char_code_at(s, k) == 9  or  _lia_char_code_at(s, k) == 10)) { k = k - 1 ;}
  if (k < 0) { return 0 ;}
  c = _lia_char_code_at(s, k);
  if (c == 41) { return 1 ;}
  if (c == 93) { return 1 ;}
  if (c >= 48  and  c <= 57) { return 1 ;}
  if (is_ident(c) == true) { return 1 ;}
  return 0;

}

pub fn jsx_scan(s: []const u8, op: []const u8, follow: []const u8, bin: i64, want_first: i64) i64 {
    var n: i64 = 0;
    var m: i64 = 0;
    var i: i64 = 0;
    var d: i64 = 0;
    var c: i64 = 0;
    var best: i64 = 0;
    var ok: i64 = 0;

  n = _lia_len(s);
  m = _lia_len(op);
  i = 0;
  d = 0;
  c = 0;
  best = -1;
  ok = 0;
  while (i < n) {
    c = _lia_char_code_at(s, i);
    if (c == 34  or  c == 39) {
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != c) { i = i + 1 ;}
      i = i + 1;
      continue;
    }
    if (c == 40  or  c == 91) { d = d + 1; i = i + 1; continue ;}
    if (c == 41  or  c == 93) { d = d - 1; i = i + 1; continue ;}
    if (d == 0  and  starts_lit(s, i, op) == 1) {
      ok = 1;
      if (i > 0  and  _lia_char_code_at(s, i - 1) == _lia_char_code_at(op, 0)) { ok = 0 ;}
      if (i + m < n  and  jsx_has(follow, _lia_char_code_at(s, i + m)) == 1) { ok = 0 ;}
      if (bin == 1  and  jsx_prev_value(s, i) == 0) { ok = 0 ;}
      if (ok == 1) {
        if (want_first == 1) { return i ;}
        best = i;
      }
    }
    i = i + 1;
  }
  return best;

}

pub fn jsx_colon(s: []const u8, pq: i64) i64 {
    var n: i64 = 0;
    var i: i64 = 0;
    var d: i64 = 0;
    var t: i64 = 0;
    var c: i64 = 0;

  n = _lia_len(s);
  i = pq + 1;
  d = 0;
  t = 0;
  c = 0;
  while (i < n) {
    c = _lia_char_code_at(s, i);
    if (c == 40  or  c == 91) { d = d + 1; i = i + 1; continue ;}
    if (c == 41  or  c == 93) { d = d - 1; i = i + 1; continue ;}
    if (d == 0  and  c == 63) { t = t + 1 ;}
    if (d == 0  and  c == 58) {
      if (t == 0) { return i ;}
      t = t - 1;
    }
    i = i + 1;
  }
  return -1;

}

