  if (c == 33) {
    out = "js_lnot(";
    out = _lia_cat(out ,  jss_e11(slice2(e, 1, n)));
    out = _lia_cat(out ,  ")");
    return out;
  }
  if (c == 45) {
    out = "js_neg(";
    out = _lia_cat(out ,  jss_e11(slice2(e, 1, n)));
    out = _lia_cat(out ,  ")");
    return out;
