}

pub fn jss_args(a: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var d: i64 = 0;
    var st: i64 = 0;
    var c: i64 = 0;
    var first: i64 = 0;
    var seg: []const u8 = "";

  out = "";
  n = _lia_len(a);
  i = 0;
  d = 0;
  st = 0;
  c = 0;
  first = 1;
  seg = "";
  while (i <= n) {
    if (i == n) {
      seg = jss_trim(slice2(a, st, n));
      if (_lia_len(seg) > 0) {
        if (first == 0) { out = _lia_cat(out ,  ", ") ;}
        out = _lia_cat(out ,  jss_e0(slice2(a, st, n)));
        first = 0;
      }
      i = i + 1;
      continue;
    }
    c = _lia_char_code_at(a, i);
    if (c == 40  or  c == 91) { d = d + 1 ;}
    if (c == 41  or  c == 93) { d = d - 1 ;}
    if (d == 0  and  c == 44) {
      if (first == 0) { out = _lia_cat(out ,  ", ") ;}
      out = _lia_cat(out ,  jss_e0(slice2(a, st, i)));
      first = 0;
      st = i + 1;
    }
    i = i + 1;
  }
  return out;

}

pub fn jss_hex_digit(c: i64) i64 {

  if (c >= 48  and  c <= 57) { return c - 48 ;}
  if (c >= 65  and  c <= 70) { return c - 55 ;}
  if (c >= 97  and  c <= 102) { return c - 87 ;}
  return -1;

}

