    var out: []const u8 = "";
    var p: i64 = 0;

  e = jss_trim(s);
  n = _lia_len(e);
  if (n == 0) { return "0" ;}
  cl = 0;
  if (_lia_char_code_at(e, 0) == 40) {
    cl = match_paren(e, 0);
    if (cl == n - 1) { return jss_e0(slice2(e, 1, cl)) ;}
  }
  id = read_ident(e, 0);
  out = "";
  if (_lia_len(id) > 0) {
    p = skip_ws(e, _lia_len(id));
    if (p < n  and  _lia_char_code_at(e, p) == 40) {
      cl = match_paren(e, p);
      if (cl == n - 1) {
        out = _lia_cat(out ,  id);
        out = _lia_cat(out ,  "(");
        out = _lia_cat(out ,  jss_args(slice2(e, p + 1, cl)));
        out = _lia_cat(out ,  ")");
