        for (mod.fns, 0..) |*fn_item, fi| {
            if (!fn_item.ok) continue;
            if (fn_item.nparams != 1) continue; // Parallel map kernels are unary: f(x) -> y
            if (std.mem.startsWith(u8, fn_item.name, "test_")) continue; // Skip test driver vectors

            // 3. Compile VmFn stack bytecode into MirInst[]
            const mir_insts = vm_to_mir.compileVmFnToMir(
