            ) catch |err| {
                try stderr.print("gpu-verify: skipping {s}, MIR compilation: {any}\n", .{ fn_item.name, err });
                continue;
            };

            const blk_slice = try LIA_ALLOC.alloc(mir_engine.MirBlock, 1);
            blk_slice[0] = .{ .id = 0, .instructions = mir_insts };
            const param_types = try LIA_ALLOC.alloc(mir_engine.MirType, 1);
            param_types[0] = .i64;

            try mir_funcs.append(.{
                .name = fn_item.name,
                .params = param_types,
                .returns = .i32,
                .blocks = blk_slice,
            });
            try kernel_names.append(fn_item.name);
            try fn_indices.append(fi);
        }

        if (mir_funcs.items.len == 0) {
            try stderr.print("gpu-verify: no valid unary kernels found in {s}\n", .{file_path});
