            try stderr.print("verify-cert: malformed .expected_outputs\n", .{});
            std.process.exit(1);
        };
        const exp_slice = cert_content[exp_val_start..exp_val_end];

        var expected_vals: [32]i64 = undefined;
        var exp_count: usize = 0;
        var it = std.mem.splitSequence(u8, exp_slice, ",");
        while (it.next()) |num_str| {
            const trimmed = std.mem.trim(u8, num_str, " \t\r\n");
            if (trimmed.len == 0) continue;
            if (exp_count < 32) {
                expected_vals[exp_count] = try std.fmt.parseInt(i64, trimmed, 10);
                exp_count += 1;
            }
        }

        if (exp_count != 32) {
            try stderr.print("verify-cert: expected 32 outputs, found {d}\n", .{exp_count});
            std.process.exit(1);
        }

        const src_file = try std.fs.cwd().openFile(target_file, .{});
        defer src_file.close();
        const src = try src_file.readToEndAlloc(LIA_ALLOC, 10 * 1024 * 1024);
        defer LIA_ALLOC.free(src);

        const mod = try vmBuild(LIA_ALLOC, src);
        const fi = vmFind(&mod, fn_name) orelse {
            try stdout.print("@RULEL:LIN_CERT_VERIFICATION:1.0.0\n.status=\"VERIFICATION_FAILED\"\n.reason=\"function_not_found_in_target\"\n", .{});
            return;
        };
        const f = &mod.fns[fi];
        if (!f.ok) {
            try stdout.print("@RULEL:LIN_CERT_VERIFICATION:1.0.0\n.status=\"VERIFICATION_FAILED\"\n.reason=\"function_rejected\"\n", .{});
            return;
        }

        var mismatches: usize = 0;
        var k: u6 = 0;
        while (k < 32) : (k += 1) {
            const e_k: i64 = @as(i64, 1) << k;
            const call_args = [_]i64{e_k};
            var steps: u64 = 0;
            const actual = try vmExec(&mod, fi, &call_args, 0, &steps);
            if (actual != expected_vals[k]) {
                mismatches += 1;
            }
        }

        try stdout.print("@RULEL:LIN_CERT_VERIFICATION:1.0.0\n", .{});
        try stdout.print(".certificate=\"{s}\"\n", .{args[2]});
        try stdout.print(".target=\"{s}::{s}\"\n", .{ target_file, fn_name });
        if (mismatches == 0) {
            try stdout.print(".status=\"VERIFIED_OK\"\n.basis_cases=32\n.mismatches=0\n.proof=\"DE_BRUIJN_REVERIFICATION_EXACT\"\n", .{});
        } else {
